INSERT INTO "public"."certificate_templates" ("id", "name", "description", "html_template", "css_template", "logo_url", "background_url", "primary_color", "secondary_color", "active", "created_at", "updated_at") VALUES
	('41111111-1111-1111-1111-111111111111', 'Template Cyberpunk', 'Template ottimizzato e ridimensionato per formato A4 Landscape (297x210mm) in stile Cyberpunk, con spaziature compatte per garantire la perfetta visualizzazione di tutti i testi.', '<div class="certificate-container">
  <div class="bg-shape shape-1"></div>
  <div class="bg-shape shape-2"></div>
  <div class="certificate-card">
    <div class="header">
      <div class="logo-wrapper">
        <img src="{{logoUrl}}" alt="Logo Piattaforma" class="logo" />
      </div>
      <div class="badge-official">ATTESTATO DI MERITO</div>
    </div>

    <div class="body">
      <p class="tagline">Si attesta con la presente che lo studente</p>
      <h1 class="student-name">{{studentName}}</h1>
      <p class="description">ha completato con successo e profitto il percorso formativo</p>
      <h2 class="course-title">{{courseTitle}}</h2>
      <div class="score-container">
        <span class="score-label">Valutazione Finale</span>
        <span class="score-value">{{score}}%</span>
      </div>
    </div>

    <div class="footer">
      <div class="footer-block">
        <p class="label">Data di Rilascio</p>
        <p class="value">{{date}}</p>
      </div>

      <div class="footer-block signature-block">
        <div class="sig-line"></div>
        <p class="sig-name">Prof. Giuseppe Carnabuci</p>
        <p class="sig-title">Direttore Didattico - GCProf AI Academy</p>
      </div>

      <div class="footer-block">
        <p class="label">ID Certificato</p>
        <p class="value">{{certificateNumber}}</p>
      </div>
    </div>
  </div>
</div>', '@import url(''https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;700;900&family=Rajdhani:wght@400;500;600;700&display=swap'');

/* Impostazioni di stampa per A4 Orizzontale (Landscape) */
@page {
  size: A4 landscape;
  margin: 0;
}

body {
  margin: 0;
  padding: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background: #050505; 
}

.certificate-container {
  position: relative;
  width: 297mm;
  height: 210mm;
  background-color: #0b0c10;
  /* Pattern a griglia stile Cyberpunk */
  background-image: 
    linear-gradient(rgba(0, 243, 255, 0.07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 243, 255, 0.07) 1px, transparent 1px);
  background-size: 20px 20px;
  box-sizing: border-box;
  overflow: hidden;
  font-family: ''Rajdhani'', sans-serif;
  color: #c5c6c7;
  padding: 10mm;
  box-shadow: 0 0 50px rgba(0, 243, 255, 0.1); 
}

/* Bagliori al neon sullo sfondo */
.bg-shape {
  position: absolute;
  z-index: 1;
  border-radius: 50%;
  filter: blur(85px);
  opacity: 0.45;
}
.shape-1 {
  width: 400px;
  height: 400px;
  background: #ff007f; /* Neon Magenta */
  top: -100px;
  left: -100px;
}
.shape-2 {
  width: 450px;
  height: 450px;
  background: #00f3ff; /* Neon Cyan */
  bottom: -150px;
  right: -100px;
}

.certificate-card {
  position: relative;
  z-index: 2;
  background: rgba(11, 12, 16, 0.9);
  padding: 15mm 25mm;
  border-radius: 4px;
  /* Bordo illuminato al neon */
  border: 1px solid rgba(0, 243, 255, 0.5);
  border-top: 6px solid #ff007f;
  border-bottom: 6px solid #00f3ff;
  box-shadow: 0 0 25px rgba(0, 243, 255, 0.15), inset 0 0 20px rgba(255, 0, 127, 0.05);
  text-align: center;
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

/* Watermark olografico */
.certificate-card::after {
  content: ''GCPROF-ACADEMY.COM'';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-20deg);
  font-size: 4.5rem;
  font-family: ''Orbitron'', sans-serif;
  color: rgba(0, 243, 255, 0.03);
  font-weight: 900;
  white-space: nowrap;
  pointer-events: none;
  z-index: 0;
  letter-spacing: 6px;
  text-shadow: 0 0 10px rgba(0, 243, 255, 0.05);
}

.header, .body, .footer {
  position: relative;
  z-index: 10;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo-wrapper {
  display: flex;
  align-items: center;
}
.logo {
  max-height: 75px;
  width: auto;
  object-fit: contain;
  filter: drop-shadow(0 0 10px rgba(0, 243, 255, 0.6));
}

.badge-official {
  background: rgba(0, 243, 255, 0.1);
  color: #00f3ff;
  padding: 0.6rem 1.5rem;
  border-radius: 2px;
  border: 1px solid #00f3ff;
  font-family: ''Orbitron'', sans-serif;
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  box-shadow: 0 0 15px rgba(0, 243, 255, 0.3);
  text-shadow: 0 0 5px rgba(0, 243, 255, 0.5);
}

.body {
  margin: 5px 0;
}

.tagline {
  color: #f2a900; /* Cyber Yellow */
  font-family: ''Orbitron'', sans-serif;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 0.4rem;
  font-weight: 600;
}

.student-name {
  font-family: ''Orbitron'', sans-serif;
  font-size: 3rem;
  color: #ffffff;
  margin: 0.2rem 0 0.6rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0px rgba(255, 0, 127, 0.8), -2px -2px 0px rgba(0, 243, 255, 0.8);
}

.description {
  color: #c5c6c7;
  font-size: 1.1rem;
  margin-bottom: 0.3rem;
  font-weight: 500;
}

.course-title {
  font-family: ''Orbitron'', sans-serif;
  font-size: 1.8rem;
  color: #00f3ff;
  font-weight: 700;
  margin: 0.4rem 0 1rem;
  line-height: 1.2;
  text-transform: uppercase;
  letter-spacing: 1px;
  text-shadow: 0 0 10px rgba(0, 243, 255, 0.4);
}

.score-container {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: rgba(255, 0, 127, 0.05);
  padding: 0.5rem 2rem;
  border-radius: 2px;
  border: 1px solid #ff007f;
  box-shadow: 0 0 15px rgba(255, 0, 127, 0.2);
}
.score-label {
  color: #c5c6c7;
  font-weight: 600;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-family: ''Orbitron'', sans-serif;
}
.score-value {
  color: #ff007f;
  font-family: ''Orbitron'', sans-serif;
  font-size: 1.5rem;
  font-weight: 800;
  text-shadow: 0 0 12px rgba(255, 0, 127, 0.6);
}

.footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding-top: 1rem;
  border-top: 1px dashed rgba(0, 243, 255, 0.3);
}

.footer-block {
  flex: 1;
  text-align: center;
}
.footer-block .label {
  color: #f2a900;
  font-family: ''Orbitron'', sans-serif;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 0.3rem;
  font-weight: 600;
}
.footer-block .value {
  color: #ffffff;
  font-weight: 700;
  font-size: 1rem;
  letter-spacing: 1px;
}

.signature-block {
  flex: 1.5;
  padding: 0 1.5rem;
}
.sig-line {
  width: 85%;
  height: 2px;
  background: #00f3ff;
  margin: 0 auto 0.5rem;
  box-shadow: 0 0 8px rgba(0, 243, 255, 0.8);
}
.sig-name {
  font-family: ''Orbitron'', sans-serif;
  font-size: 1.15rem;
  font-weight: 700;
  color: #ffffff;
  margin: 0 0 0.2rem;
  text-shadow: 0 0 5px rgba(255, 255, 255, 0.3);
}
.sig-title {
  font-size: 0.85rem;
  color: #ff007f;
  font-weight: 700;
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 1px;
}', '/gcprof-ai-academy_logo_01.png', NULL, '#00f3ff', '#ff007f', true, '2026-08-04 20:59:54.322438+00', '2026-08-04 21:04:31.486012+00'),
