/* Impostazioni di stampa per A4 Orizzontale (Landscape) */
@page {
  size: A4 landscape;
  margin: 0;
}

body {
  margin: 0;
  padding: 0;
  /* Centra il certificato nello schermo se visualizzato nel browser */
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background: #cbd5e1; 
}

.certificate-container {
  position: relative;
