  overflow: hidden;
  font-family: ''Montserrat'', sans-serif;
  color: #334155;
  padding: 15mm;
  /* Ombra per la visualizzazione a schermo, invisibile in stampa */
  box-shadow: 0 20px 40px rgba(0,0,0,0.15); 
}

.bg-shape {
  position: absolute;
  z-index: 1;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.35;
}
.shape-1 {
  width: 450px;
  height: 450px;
