INSERT INTO "public"."quizzes" ("id", "title", "description", "status", "penalty_enabled", "negative_mark", "max_score", "created_by", "created_at", "updated_at", "passing_score", "course_id", "module_id") VALUES
	('059f730b-e762-4c74-aa88-5e49df5a4c8f', 'INFO1 - Fondamenti di Google Sheets', 'Un quiz di autovalutazione sulle funzioni e gli strumenti di base di Fogli Google.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-07-19 19:37:22.805869+00', '2026-08-02 14:27:11.962+00', 60.00, 'e5efed14-cf07-4530-916a-1a1d3f43822a', '844a247f-dacd-48c5-960b-ccfa70cf0026'),
	('7a60dda4-5ebe-4e81-a138-b46db645be54', 'AI - M2 - Prompt Engineering (Fondamenti)', 'Quiz di verifica finale sui concetti chiave del Modulo 2: tecniche Zero/One/Few Shot, delimitatori, prompting strutturato (XML/Markdown/JSON) e template parametrizzati.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-07-28 10:25:53.221081+00', '2026-08-01 17:28:23.744+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('00368389-7e25-4d6f-92dd-c1f176af6786', 'AI - M3: Etica e Normativa', 'Quiz conclusivo per verificare le conoscenze su copyright, GDPR e AI Act europeo.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-01 17:28:05.914487+00', '2026-08-01 17:28:25.253+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('38f824c0-5f6b-4a71-8e7f-6999b4c6b27e', 'AI - M1 - Fondamenti di Intelligenza Artificiale', 'Quiz di verifica finale sui concetti chiave del Modulo 1: storia dell''AI, differenza tra AI/Machine Learning/Deep Learning, reti neurali, LLM e AI Agent.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-07-28 10:15:08.196658+00', '2026-07-28 18:49:42.933+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('f1aeab9c-f015-413e-a803-9455e46122ab', 'AI - M4: Python per AI', 'Quiz conclusivo per verificare le conoscenze su ambiente di sviluppo, virtualenv, librerie fondamentali e OOP in Python.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-01 19:21:39.799426+00', '2026-08-01 19:21:56.455+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('5718b4de-2c31-4ec0-ae45-7da0a6dabb6a', 'AI - M5: Data Analysis', 'Quiz conclusivo per verificare le conoscenze su EDA, pulizia dati, preprocessing, feature engineering e visualizzazione.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-01 19:21:49.485559+00', '2026-08-01 19:21:57.915+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('cf4b1a86-fac6-4a03-804e-a3b00ddaf60e', 'AI - M6: Machine Learning', 'Quiz conclusivo per verificare le conoscenze su apprendimento supervisionato/non supervisionato, validazione, metriche e overfitting.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-01 19:26:32.932313+00', '2026-08-01 19:26:42.426+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('e239c425-8aa3-451e-afe7-f488209af996', 'AI - M7: Prompt Engineering Avanzato', 'Quiz conclusivo per verificare le conoscenze su Chain of Thought, ReAct, Structured Output, Function Calling e MCP.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-01 19:36:21.759329+00', '2026-08-01 19:36:29.569+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('310d9088-fbbb-42d2-a012-fa99941fdaca', 'AI - M8: Deep Learning', 'Quiz conclusivo per verificare le conoscenze su neuroni artificiali, backpropagation, funzioni di attivazione, CNN e RNN/LSTM/GRU.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-02 08:23:36.076374+00', '2026-08-02 08:23:42.831+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('ab172063-7783-46dc-80e6-6e18c4dea014', 'AI - M9: Transformer', 'Quiz conclusivo per verificare le conoscenze su tokenizzazione, embedding, self-attention, multi-head attention e architetture Encoder/Decoder.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-02 13:38:35.201724+00', '2026-08-02 13:38:50.161+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('470ec89f-304d-4c12-969b-64ec45fc60c1', 'AI - M10: LLM Engineering', 'Quiz conclusivo per verificare le conoscenze su quantizzazione, GGUF, Ollama/vLLM/llama.cpp e architetture RAG.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-02 13:38:43.437201+00', '2026-08-02 13:38:51.461+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('7d844873-5fed-444a-8c31-b6667836929f', 'AI - M12: Sicurezza AI', 'Quiz conclusivo per verificare le conoscenze su Prompt Injection, Jailbreak, Prompt Leakage, Data Poisoning, Adversarial Attacks, Deepfake, Watermark e AI Detection.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-03 14:22:17.008359+00', '2026-08-03 14:24:53.095+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('2faba122-12af-4522-9adc-67f5ed57b657', 'AI - M13: AI Future Tech', 'Quiz conclusivo per verificare le conoscenze su Quantum AI, Neuromorphic Computing, Edge AI, TinyML, Robotica avanzata, AGI e ASI.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-03 14:24:26.136081+00', '2026-08-03 14:25:21.856+00', 60.00, '326e1451-18ff-4745-89dd-4cbc574752f0', '82a15093-20d7-4cbb-892b-a1920485d756'),
	('442505ec-ddb3-4840-856b-2b786f0b196f', 'Finance 1° - M4 - Strumenti Finanziari', 'Quiz di verifica finale sui concetti chiave del Modulo 4: azioni, obbligazioni, fondi comuni, ETF e introduzione alle criptovalute.', 'active', true, 0.25, 10.00, '08be3132-7d36-46c3-9d31-2b1fd0b48d83', '2026-08-04 10:54:05.537336+00', '2026-08-04 10:59:58.834+00', 60.00, '8ba792dc-39a6-4ca8-a3b7-96385a8259a0', 'ef22d24e-02df-4587-a56d-db1917a8d0e3'),
