INSERT INTO "public"."quiz_options" ("id", "question_id", "text", "is_correct") VALUES
	('691a42da-874d-4439-9373-febf114f36c3', '4280f99e-f9c1-4425-864c-d0033a95f38f', 'Grid funziona solo nei browser mobili, Flexbox solo nei browser desktop.', false),
	('c2de7868-6724-4180-b02e-2b945d9dbf2e', '4280f99e-f9c1-4425-864c-d0033a95f38f', 'Grid è pensato per layout bidimensionali (righe e colonne contemporaneamente), Flexbox per layout monodimensionali (una riga o una colonna alla volta).', true),
	('55f3a695-c34e-4062-9e5e-8ae6b8ecb092', '4280f99e-f9c1-4425-864c-d0033a95f38f', 'Flexbox può essere usato solo per il testo, Grid solo per le immagini.', false),
	('92f4f1ad-b1e3-40d2-8974-09aff3a05c94', '4280f99e-f9c1-4425-864c-d0033a95f38f', 'Non c''è alcuna differenza pratica tra i due strumenti.', false),
	('014f9e8d-de6a-423c-a735-df700e684a66', '3d19e673-e592-473c-90de-8c4016e40c21', 'A indicare la fine dell''algoritmo.', false),
	('e66cd545-b088-479b-9e85-10d86fb1c771', '3d19e673-e592-473c-90de-8c4016e40c21', 'A rappresentare l''assegnazione di un valore a una variabile, distinguendola dall''uguaglianza matematica.', true),
	('a22c5ee3-bb74-4252-8f59-1b8b90aaa692', '3d19e673-e592-473c-90de-8c4016e40c21', 'A separare due istruzioni consecutive.', false),
	('820e50a2-2fa8-469b-a7ad-f717fdfd8712', '3d19e673-e592-473c-90de-8c4016e40c21', 'A indicare un''operazione di lettura da tastiera.', false),
